// Solid pop — opacity snaps to 100% fast (boxes never linger translucent), scale settles.
const pop = (p: number) => ({
  opacity: Math.min(1, p * 6),
  transform: `scale(${interpolate(p, [0, 1], [0.72, 1])})`,
});

// Decaying shake inside a [start, start+dur] window — for the "it fails" jitter.
const shake = (f: number, start: number, dur: number, amp: number, freq = 1.1) => {
  if (f < start || f > start + dur) return 0;
  const t = (f - start) / dur;
  return Math.sin((f - start) * freq) * amp * (1 - t);
};

// Orange "denied" mark — circle + X.
const DeniedMark: React.FC<{ s: number; p: number }> = ({ s, p }) => (
  <div style={{ ...pop(p), display: "flex" }}>
    {svgWrap(s, (
      <>
        <circle {...L(2.4, ACCENT, { cx: 12, cy: 12, r: 10 })} />
        <path {...L(2.6, ACCENT, { d: "M8.5 8.5l7 7 M15.5 8.5l-7 7" })} />
      </>
    ))}
  </div>
);

// compound phase style (LOCAL frames). `hold` skips the exit fade (final beat).
function phase(
  frame: number,
  vfps: number,
  start: number,
  dur: number,
  opts: { preset?: any; ty?: number; scaleFrom?: number; blurFrom?: number; inDelay?: number; exitFrames?: number; hold?: boolean } = {}
) {
  const { preset = "SNAPPY", ty = 30, scaleFrom = 0.94, blurFrom = 6, inDelay = 0, exitFrames = 14, hold = false } = opts;
  const local = frame - start;
  const enter = springIn(local, vfps, inDelay, preset);
  const out = hold ? 1 : interpolate(local, [dur - exitFrames, dur], [1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const opacity = Math.max(0, Math.min(enter, out));
  return {
    opacity,
    transform: `translateY(${interpolate(enter, [0, 1], [ty, 0])}px) scale(${interpolate(enter, [0, 1], [scaleFrom, 1])})`,
    filter: `blur(${interpolate(enter, [0, 1], [blurFrom, 0])}px)`,
  };
}

const Badge: React.FC<{ base: number; p: number; kind: "check" | "lock" | "coin"; open?: number }> = ({ base, p, kind, open = 0 }) => {
