};

// =============================================================================
// SECTION 1 — OPENING : capabilities work → web data fails → quits → it pays
// =============================================================================

const Tile: React.FC<{ base: number; p: number; active?: boolean; children: React.ReactNode }> = ({ base, p, active, children }) => (
  <div
    style={{
      position: "relative",
      width: base * 0.16,
      height: base * 0.16,
      borderRadius: base * 0.022,
      background: C.card,
      border: `${Math.max(2, base * 0.0022)}px solid ${active ? ACCENT : C.border}`,
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      ...pop(p),
    }}
  >
    {children}
  </div>
);

const Connector: React.FC<{ base: number; p: number }> = ({ base, p }) => (
  <div style={{ width: base * 0.05, height: Math.max(2, base * 0.0026), background: C.border, opacity: p, transformOrigin: "left", transform: `scaleX(${p})` }} />
);

const Opening: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);
  const exit = sceneExit(frame, OPENING_DUR);

  // 0:00–0:05  capabilities tick off
  const t = [0, 1, 2, 3].map((i) => staggeredSpring(frame, vfps, i, 8, 16, "ELASTIC"));
  const conn = [0, 1, 2].map((i) => springIn(frame, vfps, 20 + i * 16, "LIQUID"));
  const checks = [0, 1, 2].map((i) => springIn(frame, vfps, 30 + i * 16, "ELASTIC"));

  // 0:05–0:10  it fails → card rejected → it quits
  const failFlash = interpolate(frame, [116, 126, 142, 152], [0, 1, 1, 0], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const cardRise = springIn(frame, vfps, 150, "LIQUID");
  const cardDenied = springIn(frame, vfps, 182, "ELASTIC");
  const cardFall = interpolate(frame, [206, 232], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });
  const lockSlam = springIn(frame, vfps, 198, "ELASTIC");
  const q = interpolate(frame, [236, 262], [0, 1], { extrapolateLeft: "clamp", extrapolateRight: "clamp" });

  // 0:10–0:12  "But from today it doesn't" — hard flip
  const paid = frame >= 263;
  const unlock = springIn(frame, vfps, 263, "LIQUID");
  const coinIn = springIn(frame, vfps, 273, "ELASTIC");
  const ring = springIn(frame, vfps, 263, "LIQUID");

  const sh = shake(frame, 116, 30, base * 0.0045) + shake(frame, 152, 52, base * 0.0055);
  const iconC = base * 0.085;
  const tile4Op = paid ? 1 : interpolate(q, [0, 1], [1, 0.4]);
  const globeColor = paid ? ACCENT : C.textMuted;

  const conn3Scale = paid ? interpolate(unlock, [0, 1], [0.35, 1]) : interpolate(q, [0, 1], [1, 0.3]);
  const conn3Color = paid ? ACCENT : C.border;
  const conn3Op = conn[2] * (paid ? 1 : interpolate(q, [0, 1], [1, 0.35]));

  return (
    <AbsoluteFill style={{ opacity: exit.opacity, transform: exit.transform }}>
      <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", paddingLeft: width * 0.04 }}>
        <div style={{ display: "flex", alignItems: "center", gap: base * 0.03 }}>
          {/* tile 1 — plan */}
          <div style={{ position: "relative" }}>
            <Tile base={base} p={t[0]}><IconPlan s={iconC} c={C.textMuted} /></Tile>
            <Badge base={base} p={checks[0]} kind="check" />
          </div>
          <Connector base={base} p={conn[0]} />
          {/* tile 2 — code */}
          <div style={{ position: "relative" }}>
            <Tile base={base} p={t[1]}><IconCode s={iconC} c={C.textMuted} /></Tile>
            <Badge base={base} p={checks[1]} kind="check" />
          </div>
          <Connector base={base} p={conn[1]} />
          {/* tile 3 — API */}
          <div style={{ position: "relative" }}>
            <Tile base={base} p={t[2]}><IconApi s={iconC} c={C.textMuted} /></Tile>
            <Badge base={base} p={checks[2]} kind="check" />
          </div>
          {/* connector 3 — breaks, then surges */}
          <div style={{ width: base * 0.05, height: Math.max(2, base * 0.0026), background: conn3Color, opacity: conn3Op, transformOrigin: "left", transform: `scaleX(${conn3Scale})` }} />
          {/* tile 4 — web data: fails → quits → pays */}
          <div style={{ position: "relative", transform: `translateX(${sh}px)` }}>
            <div
              style={{
                position: "absolute",
                inset: 0,
                borderRadius: base * 0.04,
                border: `${Math.max(2, base * 0.0024)}px solid ${ACCENT}`,
                opacity: paid ? interpolate(ring, [0, 1], [0.85, 0]) : 0,
                transform: `scale(${interpolate(ring, [0, 1], [0.95, 1.45])})`,
              }}
            />
            <Tile base={base} p={t[3]} active={paid}>
              <div style={{ opacity: tile4Op, display: "flex" }}>
                <IconGlobe s={iconC} c={globeColor} />
              </div>
            </Tile>

            {!paid && <Badge base={base} p={lockSlam} kind="lock" open={0} />}
            {paid && unlock < 0.55 && <Badge base={base} p={1} kind="lock" open={unlock} />}
            {paid && unlock >= 0.55 && <Badge base={base} p={coinIn} kind="coin" />}

            {!paid && (
              <div style={{ position: "absolute", left: "50%", top: "50%", transform: "translate(-50%,-50%)", opacity: failFlash }}>
                <DeniedMark s={base * 0.075} p={1} />
              </div>
            )}

            {!paid && (
              <div
                style={{
                  position: "absolute",
                  left: "50%",
                  top: "100%",
                  transform: `translate(-50%, ${interpolate(cardRise, [0, 1], [base * 0.06, -base * 0.04])}px) translateY(${cardFall * base * 0.13}px)`,
                  opacity: cardRise * (1 - cardFall),
                }}
              >
                <div style={{ position: "relative", display: "flex" }}>
                  <div style={{ background: C.card, border: `${Math.max(2, base * 0.002)}px solid ${C.border}`, borderRadius: base * 0.012, padding: base * 0.012 }}>
                    <IconCard s={base * 0.058} c={C.textMuted} />
                  </div>
                  <div style={{ position: "absolute", left: "50%", top: "50%", transform: "translate(-50%,-50%)" }}>
                    <DeniedMark s={base * 0.052} p={cardDenied} />
                  </div>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

// =============================================================================
// SECTION 3 — EXPLAINER : pay-per-use → x402 → HTTP 402 flow → allowance
// =============================================================================

const Node: React.FC<{ base: number; p: number; active?: boolean; children: React.ReactNode }> = ({ base, p, active, children }) => (
