// A single gold coin (opaque orange disc, darker rim). `dollar` stamps the top
// coin; `bright` glows the coins that were actually spent.
const Coin: React.FC<{ d: number; base: number; dollar?: boolean; bright?: boolean }> = ({ d, base, dollar, bright }) => (
