        width: d * 0.6,
        height: d * 0.6,
        borderRadius: "50%",
        border: `${Math.max(1, base * 0.0012)}px solid ${C.orangeDeep}`,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
      }}
    >
      {dollar && <span style={{ fontFamily: F.marketing, fontWeight: 600, fontSize: d * 0.46, color: C.bg, lineHeight: 1 }}>$</span>}
    </div>
