// SECTION 5 — CLOSING : store grid → agent earns → [blank CTA slot]
// =============================================================================

// Distinct tool glyphs so tiles read as different TOOLS, not empty boxes.
const TILE_ICONS: React.FC<IconProps>[] = [
  IconGlobe, IconChart, IconPlay, IconTerminal, IconPosts, IconFlag,
  IconWallet, IconServer, IconCode, IconApi, IconPlan, IconCard,
];

// One tile in the catalog stream. `lit` (0→1) brightens it as it crosses the beam.
const StreamTile: React.FC<{ base: number; tile: number; Icon: React.FC<IconProps>; lit: number }> = ({ base, tile, Icon, lit }) => (
  <div
    style={{
      position: "relative",
      width: tile,
      height: tile,
      borderRadius: base * 0.014,
      background: C.card,
      border: `${Math.max(2, base * 0.0018)}px solid ${C.border}`,
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      transform: `scale(${1 + lit * 0.06})`,
    }}
  >
    {/* orange tint + border light up only when crossing the beam (nested in opaque tile) */}
    <div style={{ position: "absolute", inset: 0, borderRadius: base * 0.014, background: ACCENT, opacity: lit * 0.16 }} />
    <div style={{ position: "absolute", inset: 0, borderRadius: base * 0.014, border: `${Math.max(2, base * 0.0022)}px solid ${ACCENT}`, opacity: lit }} />
    <Icon s={tile * 0.5} c={lit > 0.5 ? ACCENT : C.textSubtle} sw={2} />
  </div>
);

// Concept-workflow winner: an endless river of distinct tool tiles streams past
// a docked x402 node whose beam lights tiles as they pass — abundance + access.
const CatalogStream: React.FC<{ base: number; width: number; height: number; f: number; vfps: number; countIn: number }> = ({ base, width, height, f, vfps, countIn }) => {
  const clamp = { extrapolateLeft: "clamp" as const, extrapolateRight: "clamp" as const };
  const cols = 5;
  const tile = base * 0.092;
  const pitch = tile * 1.28;
  const colGap = base * 0.03;
  const bandH = height * 0.68;
  const K = Math.ceil(bandH / pitch) + 2;
  const totalH = K * pitch;
  const speed = pitch / 54; // calm: ~1 tile-pitch every ~54 frames
  const bandW = cols * tile + (cols - 1) * colGap;
  const bandIn = springIn(f, vfps, 4, "LIQUID");
  const contactY = bandH / 2;
  const beamOn = interpolate(f, [40, 62], [0, 1], clamp);
  const coinIn = springIn(f, vfps, 24, "ELASTIC");
  const coinX = width * 0.5;
  const bandRight = width * 0.055;
  const bandLeftX = width - bandRight - bandW;
  const centerY = height / 2;
  const flash = interpolate(f, [10, 18, 30], [0, 1, 0], clamp);

  const columns: React.ReactNode[] = [];
  for (let c = 0; c < cols; c++) {
    const dir = c % 2 === 0 ? 1 : -1;
    const distC = Math.abs(c - (cols - 1) / 2);
    const colScale = 1 - distC * 0.07;
    const colOp = (1 - distC * 0.17) * bandIn;
    const tiles: React.ReactNode[] = [];
    for (let i = 0; i < K; i++) {
      const yRaw = (((i * pitch - f * speed * dir) % totalH) + totalH) % totalH;
      const y = yRaw - pitch;
      const prox = Math.max(0, 1 - Math.abs(y + tile / 2 - contactY) / (pitch * 0.6));
      const lit = prox * beamOn;
      const Icon = TILE_ICONS[(c * 5 + i) % TILE_ICONS.length];
      tiles.push(
        <div key={i} style={{ position: "absolute", left: 0, top: y, width: tile, height: tile }}>
          <StreamTile base={base} tile={tile} Icon={Icon} lit={lit} />
        </div>
      );
    }
    columns.push(
      <div key={c} style={{ position: "relative", width: tile, height: bandH, opacity: colOp, transform: `scale(${colScale})`, transformOrigin: "center" }}>
        {tiles}
      </div>
    );
  }

  return (
    <>
      {/* 1,000s / AI tools */}
      <div style={{ position: "absolute", left: width * 0.09, top: "50%", transform: `translateY(calc(-50% + ${interpolate(countIn, [0, 1], [20, 0])}px))`, opacity: countIn, display: "flex", flexDirection: "column", gap: base * 0.006 }}>
        <span style={{ fontFamily: F.marketing, fontWeight: 600, fontSize: base * 0.17, color: C.text, letterSpacing: "-0.04em", lineHeight: 0.9 }}>
          1,000<span style={{ color: ACCENT, display: "inline-block", transform: `scale(${1 + flash * 0.12})` }}>s</span>
        </span>
        <span style={{ fontFamily: F.primary, fontWeight: 500, fontSize: base * 0.032, color: C.textMuted }}>AI tools</span>
      </div>

      {/* beam from the x402 node into the catalog */}
      <div style={{ position: "absolute", left: coinX, top: centerY, height: Math.max(2, base * 0.0026), width: bandLeftX - coinX, background: ACCENT, opacity: 0.5 * beamOn, transformOrigin: "left", transform: `translateY(-50%) scaleX(${beamOn})` }} />

      {/* x402 node */}
      <div style={{ position: "absolute", left: coinX, top: centerY, transform: `translate(-50%, -50%) scale(${interpolate(coinIn, [0, 1], [0.6, 1])})`, opacity: Math.min(1, coinIn * 4), width: base * 0.12, height: base * 0.12, borderRadius: "50%", background: C.card, border: `${Math.max(3, base * 0.003)}px solid ${ACCENT}`, display: "flex", alignItems: "center", justifyContent: "center" }}>
        <span style={{ fontFamily: F.marketing, fontWeight: 600, fontSize: base * 0.034, color: C.text, letterSpacing: "-0.02em" }}>x<span style={{ color: ACCENT }}>402</span></span>
      </div>

      {/* the catalog stream — endless, edge-masked */}
      <div
        style={{
          position: "absolute",
          right: bandRight,
          top: "50%",
          transform: "translateY(-50%)",
          height: bandH,
          width: bandW,
          display: "flex",
          gap: colGap,
          WebkitMaskImage: "linear-gradient(to bottom, rgba(0,0,0,0) 0%, rgba(0,0,0,1) 13%, rgba(0,0,0,1) 87%, rgba(0,0,0,0) 100%)",
          maskImage: "linear-gradient(to bottom, rgba(0,0,0,0) 0%, rgba(0,0,0,1) 13%, rgba(0,0,0,1) 87%, rgba(0,0,0,0) 100%)",
        }}
      >
        {columns}
      </div>
    </>
  );
};

const Closing: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps, width, height } = useVideoConfig();
  const base = Math.min(width, height);

  const CL1 = phase(frame, vfps, 0, 245, { preset: "SNAPPY", ty: 26 });
  const CL2 = phase(frame, vfps, 230, 175, { preset: "LIQUID", ty: 26 });

  const cl1 = frame - 0;
  const countIn = springIn(cl1, vfps, 10, "LIQUID");
  const cl2 = frame - 230;
  const serverIn = springIn(cl2, vfps, 8, "SNAPPY");
  const agentIn = springIn(cl2, vfps, 16, "SNAPPY");
  const earnP = springIn(cl2, vfps, 30, "LIQUID");

  return (
    <AbsoluteFill>
      {/* CL1 — thousands of AI tools: a live catalog stream the agent taps into */}
      <div style={{ position: "absolute", inset: 0, opacity: CL1.opacity, transform: CL1.transform, filter: CL1.filter }}>
        <CatalogStream base={base} width={width} height={height} f={cl1} vfps={vfps} countIn={countIn} />
      </div>

      {/* CL2 — agent earns too (a coin flows in to the agent) */}
      <div style={{ position: "absolute", inset: 0, display: "flex", alignItems: "center", justifyContent: "center", opacity: CL2.opacity, transform: CL2.transform, filter: CL2.filter }}>
        <div style={{ position: "relative", display: "flex", alignItems: "center", gap: base * 0.16 }}>
          <Node base={base} p={serverIn}><IconServer s={base * 0.1} c={C.text} /></Node>
          <div style={{ position: "absolute", left: base * 0.2, right: base * 0.2, top: "50%", height: Math.max(2, base * 0.0026), background: C.border, transform: "translateY(-50%)" }} />
          <div style={{ position: "absolute", left: `calc(${base * 0.2}px + ${earnP} * (100% - ${base * 0.4}px))`, top: "50%", transform: "translate(-50%,-50%)" }}>
            <IconCoin s={base * 0.06} c={ACCENT} />
          </div>
          <Node base={base} p={agentIn} active><IconAgent s={base * 0.1} c={ACCENT} /></Node>
        </div>
      </div>

      {/* CTA slot intentionally BLANK (2:40–2:50) — own end card added in edit. */}
    </AbsoluteFill>
  );
};

